{"code": "async (page) => {
    // Wait for the page to load
    await page.waitForSelector('ytd-video-renderer');

    // Get all video renderers
    const videoElements = await page.$$('ytd-video-renderer');
    console.log(`Found ${videoElements.length} video renderers`);

    const results = [];
    for (let i = 0; i < Math.min(videoElements.length, 20); i++) {
        const element = videoElements[i];

        // Get the title and link
        const titleElement = await element.$('a#video-title');
        if (!titleElement) continue;

        const title = await titleElement.getAttribute('title') || await titleElement.textContent();
        const href = await titleElement.getAttribute('href');

        // Get the full URL
        const url = href ? `https://www.youtube.com${href}` : null;

        // Get channel name
        const channelElement = await element.$('ytd-channel-name a');
        const channel = channelElement ? await channelElement.textContent() : null;

        // Get views and upload time
        const metaElement = await element.$('#metadata-line');
        const meta = metaElement ? await metaElement.textContent() : null;

        results.push({
            index: i + 1,
            title: title.trim(),
            url,
            channel,
            meta
        });
    }

    return results;
}"}

