{"function": "() => {
    const el = document.querySelector('*');
    const iter = document.createNodeIterator(el, NodeFilter.SHOW_TEXT);
    let node;
    while (node = iter.nextNode()) {
        if (node.textContent.includes('The mighty polar bear')) {
            // find the parent that likely contains the whole description
            let parent = node.parentElement;
            while (parent && !parent.classList.contains('ytd-video-description-renderer')) {
                parent = parent.parentElement;
            }
            return parent ? parent.innerText : node.parentElement.innerText;
        }
    }
    return null;
}"}

