{"function": "() => {
    const transcriptPanel = document.querySelector('ytd-transcript-renderer');
    if (!transcriptPanel) return null;
    const segments = transcriptPanel.querySelectorAll('ytd-transcript-segment-renderer');
    const entries = [];
    segments.forEach(seg => {
        const time = seg.querySelector('.segment-timestamp')?.textContent?.trim();
        const text = seg.querySelector('.segment-text')?.textContent?.trim();
        if (time && text) entries.push({time, text});
    });
    if (entries.length) return entries;
    // fallback: look for buttons with timestamp and text
    const buttons = transcriptPanel.querySelectorAll('button');
    const buttonEntries = [];
    buttons.forEach(btn => {
        const spans = btn.querySelectorAll('span');
        if (spans.length >= 2) {
            const time = spans[0]?.textContent?.trim();
            const text = spans[1]?.textContent?.trim();
            if (time && text) buttonEntries.push({time, text});
        }
    });
    return buttonEntries.length ? buttonEntries : null;
}"}

