{"code": "async (page) => {
  // Function to extract comment data
  const comments = [];

  // Select all comment elements - YouTube comment selectors may vary
  // Try multiple selectors
  const commentSelectors = [
    'ytd-comment-thread-renderer',
    '#contents > ytd-comment-thread-renderer',
    'ytd-comment-thread-renderer #comment'
  ];

  for (const selector of commentSelectors) {
    const commentElements = await page.$$(selector);
    if (commentElements.length > 0) {
      for (const element of commentElements) {
        try {
          // Extract username
          const usernameElement = await element.$('#author-text');
          const username = usernameElement ? (await usernameElement.textContent()).trim() : '';

          // Extract comment text
          const commentTextElement = await element.$('#content-text');
          const commentText = commentTextElement ? (await commentTextElement.textContent()).trim() : '';

          // Extract timestamp
          const timestampElement = await element.$('#published-time-text a');
          const timestamp = timestampElement ? (await timestampElement.textContent()).trim() : '';

          // Extract likes count
          const likesElement = await element.$('#vote-count-middle');
          const likes = likesElement ? (await likesElement.textContent()).trim() : '';

          // Extract reply count
          const replyElement = await element.$('#reply-count');
          const replyCount = replyElement ? (await replyElement.textContent()).trim() : '';

          // Check if comment mentions animals or moments (simple keyword matching)
          const animalKeywords = ['sloth', 'polar bear', 'penguin', 'lion', 'animal', 'bear', 'lion', 'penguin', 'sloths', 'polar bears', 'lions', 'penguins'];
          const mentionsAnimal = animalKeywords.some(keyword => 
            commentText.toLowerCase().includes(keyword.toLowerCase())
          );

          comments.push({
            username,
            commentText,
            timestamp,
            likes,
            replyCount,
            mentionsAnimal
          });
        } catch (err) {
          console.error('Error extracting comment:', err);
        }
      }
      break;
    }
  }

  return {
    totalComments: comments.length,
    comments: comments.slice(0, 50) // limit to 50
  };
}"}

