await (async (page) => {
  // Re-extract comments with sorting
  const commentElements = await page.$$('ytd-comment-thread-renderer');
  const comments = [];

  for (const element of commentElements) {
    try {
      const usernameElement = await element.$('#author-text span');
      const username = usernameElement ? (await usernameElement.textContent()).trim() : '';

      let commentText = '';
      const contentTextElement = await element.$('#content-text');
      if (contentTextElement) {
        commentText = await contentTextElement.textContent();
        commentText = commentText.trim();
      }

      const timestampElement = await element.$('#published-time-text a');
      const timestamp = timestampElement ? (await timestampElement.textContent()).trim() : '';

      const likesElement = await element.$('#vote-count-middle');
      let likesStr = likesElement ? (await likesElement.textContent()).trim() : '0';

      // Parse likes string to number
      let likesNum = 0;
      if (likesStr.includes('K')) {
        likesNum = parseFloat(likesStr.replace('K', '')) * 1000;
      } else if (likesStr.includes('M')) {
        likesNum = parseFloat(likesStr.replace('M', '')) * 1000000;
      } else {
        likesNum = parseInt(likesStr) || 0;
      }

      const replyElement = await element.$('#reply-count');
      const replyCount = replyElement ? (await replyElement.textContent()).trim() : '';

      // Animal keywords
      const animalKeywords = ['sloth', 'polar bear', 'penguin', 'lion', 'animal', 'bear', 'penguins', 'sloths', 'polar bears', 'lions', 'polar', 'panda', 'cub'];
      const mentionsAnimal = animalKeywords.some(keyword => 
        commentText.toLowerCase().includes(keyword.toLowerCase())
      );

      comments.push({
        username,
        commentText,
        timestamp,
        likes: likesStr,
        likesNum,
        replyCount,
        mentionsAnimal
      });
    } catch (err) {
      console.error(err);
    }
  }

  // Sort: first by mentionsAnimal true, then by likesNum descending
  comments.sort((a, b) => {
    if (a.mentionsAnimal && !b.mentionsAnimal) return -1;
    if (!a.mentionsAnimal && b.mentionsAnimal) return 1;
    return b.likesNum - a.likesNum;
  });

  // Take top 50
  const top50 = comments.slice(0, 50);

  return {
    totalExtracted: comments.length,
    top50: top50.map(c => ({
      username: c.username,
      comment: c.commentText,
      timestamp: c.timestamp,
      likes: c.likes,
      mentionsAnimal: c.mentionsAnimal
    }))
  };
})(page);
```
